mapper.select:
SELECT /* LGVPAY00033.retrievePlRateList */ m.pl_rate_id , m.paid_leave_detail_code , m.emp_category_code , m.tier_no , m.from_days , m.to_days , m.base_amount_type , m.base_salary_rate , m.position_allw_rate , m.job_allw_rate , m.qualification_allw_rate , m.adj1_allw_rate , m.adj2_allw_rate , m.adj3_allw_rate , TO_CHAR(m.effective_start_date, 'DD/MM/YYYY') AS start_date , TO_CHAR(m.effective_end_date , 'DD/MM/YYYY') AS end_date , m.note FROM tb_pay_pl_rate_m m WHERE m.subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode}
AND m.paid_leave_detail_code = #{paidLeaveDetailCode}
AND TO_DATE(#{effectiveDate}, 'DD/MM/YYYY') BETWEEN m.effective_start_date AND m.effective_end_date
ORDER BY m.paid_leave_detail_code, m.effective_start_date DESC, m.emp_category_code, m.tier_no

mapper.update:
UPDATE /* LGVPAY00033.updatePlRate */ tb_pay_pl_rate_m
SET    paid_leave_detail_code  = #{paidLeaveDetailCode}
     , emp_category_code       = #{empCategoryCode}
     , tier_no                 = #{tierNo}
     , from_days               = #{fromDays}
     , to_days                 = #{toDays, jdbcType=NUMERIC}
     , base_amount_type        = NVL(#{baseAmountType, jdbcType=VARCHAR}, 'BASE_SALARY')
     , base_salary_rate        = NVL(#{baseSalaryRate, jdbcType=NUMERIC}, 0)
     , position_allw_rate      = NVL(#{positionAllwRate, jdbcType=NUMERIC}, 0)
     , job_allw_rate           = NVL(#{jobAllwRate, jdbcType=NUMERIC}, 0)
     , qualification_allw_rate = NVL(#{qualificationAllwRate, jdbcType=NUMERIC}, 0)
     , adj1_allw_rate          = NVL(#{adj1AllwRate, jdbcType=NUMERIC}, 0)
     , adj2_allw_rate          = NVL(#{adj2AllwRate, jdbcType=NUMERIC}, 0)
     , adj3_allw_rate          = NVL(#{adj3AllwRate, jdbcType=NUMERIC}, 0)
     , effective_start_date    = TO_DATE(#{startDate}, 'DD/MM/YYYY')
     , effective_end_date      = TO_DATE(NVL(#{endDate, jdbcType=VARCHAR}, '31/12/4712'), 'DD/MM/YYYY')
     , note                    = #{note, jdbcType=VARCHAR}
     , last_update_date        = SYSDATE
     , last_update_user_id     = #{applicationUserId}
WHERE  pl_rate_id = #{plRateId}

mapper.select:
SELECT /* LGVPAY00033.retrievePlItemMapList */ mp.pl_item_map_id , mp.paid_leave_detail_code , mp.tier_no , mp.component_code , TO_CHAR(mp.payroll_item_id) AS payroll_item_id , pi.payroll_item_name , mp.apply_value_type , mp.note FROM tb_pay_pl_item_map_m mp , tb_pay_payroll_item_m pi WHERE pi.payroll_item_id(+) = mp.payroll_item_id AND mp.subsidiary_code = #{LGVHR_PROJECT_SESSION.subsidiaryCode}
AND mp.paid_leave_detail_code = #{paidLeaveDetailCode}
ORDER BY mp.paid_leave_detail_code, mp.tier_no , DECODE(mp.component_code, 'BASE_SALARY', 1, 'POSITION_ALLW', 2, 'JOB_ALLW', 3, 'QUALIFICATION_ALLW', 4, 'ADJ1_ALLW', 5, 'ADJ2_ALLW', 6, 7)

mapper.update:
UPDATE /* LGVPAY00033.updatePlItemMap */ tb_pay_pl_item_map_m
SET    paid_leave_detail_code = #{paidLeaveDetailCode}
     , tier_no                = #{tierNo}
     , component_code         = #{componentCode}
     , payroll_item_id        = #{payrollItemId}
     , apply_value_type       = NVL(#{applyValueType, jdbcType=VARCHAR}, 'PAY')
     , note                   = #{note, jdbcType=VARCHAR}
     , last_update_date       = SYSDATE
     , last_update_user_id    = #{applicationUserId}
WHERE  pl_item_map_id = #{plItemMapId}
